def transform(grid):
    # The answer is the solid 3x3 patch containing the greatest variety of
    # non-background colors (the unique three-color patch in these examples).
    candidates = []
    for r in range(len(grid) - 2):
        for c in range(len(grid[0]) - 2):
            patch = [row[c:c + 3] for row in grid[r:r + 3]]
            vals = [v for row in patch for v in row]
            if 0 not in vals:
                candidates.append((len(set(vals)), patch))
    if not candidates:
        return []
    return max(candidates, key=lambda item: item[0])[1]
